import{_ as a,I as l,o as i,c as d,b6 as e,J as o}from"./chunks/framework.COUcLbTA.js";const b=JSON.parse('{"title":"实时通信机制（Polling / SSE / WebSocket）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/3-browser-and-frontend/realtime-communication.md","filePath":"zh-cn/appendix/3-browser-and-frontend/realtime-communication.md"}'),g={name:"zh-cn/appendix/3-browser-and-frontend/realtime-communication.md"};function c(_,t,T,p,S,h){const n=l("PollingDemo"),r=l("SSEDemo"),s=l("WebSocketDemo");return i(),d("div",null,[t[0]||(t[0]=e('<h1 id="实时通信机制-polling-sse-websocket" tabindex="-1">实时通信机制（Polling / SSE / WebSocket） <a class="header-anchor" href="#实时通信机制-polling-sse-websocket" aria-label="Permalink to “实时通信机制（Polling / SSE / WebSocket）”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">核心导读</p><p><strong>浏览器如何实现数据的实时更新？</strong> 传统的 HTTP 协议基于“请求-响应”模型，客户端必须主动发起请求，服务端才能返回数据。如果我们需要实现聊天室、股票行情推送等实时场景，这种模型将面临挑战。</p><p>本章将介绍前端应对实时数据通信的三种主要技术：短轮询（Polling）、服务器推送事件（SSE）与全双工 WebSocket，并探讨它们的原理与适用场景。</p></div><hr><h2 id="_1-传统-http-的局限性" tabindex="-1">1. 传统 HTTP 的局限性 <a class="header-anchor" href="#_1-传统-http-的局限性" aria-label="Permalink to “1. 传统 HTTP 的局限性”">​</a></h2><p>HTTP 协议的设计初衷是用于文档检索，它具有<strong>无状态（Stateless）</strong>和<strong>由客户端单向发起</strong>的特点：</p><ol><li>客户端发起 HTTP 请求。</li><li>服务端处理请求并返回响应。</li><li>连接完成任务后通常会释放对应的逻辑请求（HTTP/1.1 虽然支持长连接复用，但业务层面的请求-响应模型并未改变）。</li></ol><p>在此模式下，服务端无法主动将状态的改变随时通知正在等待的客户端。为了获取最新数据，必须寻找其他技术架构方案。</p><hr><h2 id="_2-短轮询-polling" tabindex="-1">2. 短轮询（Polling） <a class="header-anchor" href="#_2-短轮询-polling" aria-label="Permalink to “2. 短轮询（Polling）”">​</a></h2><p>最直接的解决方案是<strong>短轮询</strong>。即客户端利用定时器（如 <code>setInterval</code>），每隔一段固定的时间，自动向服务端发送 HTTP 请求，询问是否有新数据到达。</p>',10)),o(n),t[1]||(t[1]=e('<p><strong>技术特点与局限：</strong></p><ul><li><strong>优点</strong>：实现机制极其简单，完全依赖标准的 HTTP 协议和 AJAX/Fetch 技术。</li><li><strong>缺点</strong>：可能产生巨大的网络开销与资源浪费。大多数时间里，服务端的响应可能是“无新数据”。无论有无数据，每次请求都需要携带完整的 HTTP 头部（Headers、Cookies 等），在并发量较高的场景下，会导致网络资源被大量无意义的查询占据。</li></ul><hr><h2 id="_3-服务器推送事件-server-sent-events" tabindex="-1">3. 服务器推送事件（Server-Sent Events） <a class="header-anchor" href="#_3-服务器推送事件-server-sent-events" aria-label="Permalink to “3. 服务器推送事件（Server-Sent Events）”">​</a></h2><p>为了降低频繁建立 HTTP 连接的开销，<strong>Server-Sent Events (SSE)</strong> 提供了一种轻型的单向数据流推送架构。</p><p>SSE 建立在 HTTP 协议之上。客户端发起一个包含特殊请求头（<code>Accept: text/event-stream</code>）的 HTTP 请求后，服务端在返回响应时会保持底层的 TCP 连接不断开。随后，服务端可以通过这条持久的通道，持续不断地向客户端推送文本格式的数据。</p>',6)),o(r),t[2]||(t[2]=e('<p><strong>技术特点与局限：</strong></p><ul><li><strong>优点</strong>：连接持久化，网络开销小；浏览器原生支持断线自动重连机制；非常适合从服务端向客户端<strong>单向</strong>传输流式数据（例如大语言模型的文本逐字输出、实时交易行情推送）。</li><li><strong>缺点</strong>：通信通道是单向的。如果客户端需要向服务端发起控制指令或发送新数据，必须另外建立普通的 HTTP 请求。</li></ul><hr><h2 id="_4-websocket-全双工通信协议" tabindex="-1">4. WebSocket：全双工通信协议 <a class="header-anchor" href="#_4-websocket-全双工通信协议" aria-label="Permalink to “4. WebSocket：全双工通信协议”">​</a></h2><p>当应用场景涉及高频的双向交互（如多人在线动作游戏、精密的协同文档编辑）时，我们需要一种既能降低通信开销，又能实现真正双工通信的技术——<strong>WebSocket</strong>。</p><p>WebSocket 是一种独立的网络通信协议。它精妙地借助了 HTTP 协议来完成初始建连：</p><ol><li><strong>握手阶段</strong>：客户端发送一个特殊的 HTTP 请求，声明希望将其升级为新协议（携带 <code>Upgrade: websocket</code> 头部）。</li><li><strong>连接质变</strong>：服务端若支持并同意该协议，则回复 <code>101 Switching Protocols</code> 状态码。</li><li><strong>彻底自由</strong>：此时 HTTP 的规范使命结束，底层的 TCP 连接被移交给 WebSocket 协议。此后，客户端与服务端享有平等的全双工（Full-Duplex）通信权利，双方可随时收发极简格式的数据帧。</li></ol>',7)),o(s),t[3]||(t[3]=e('<p><strong>技术特点与局限：</strong></p><ul><li><strong>优点</strong>：支持真正意义上的双向实时通信；数据帧的头部信息极小，通信延迟低、吞吐效率高；支持原生二进制数据（ArrayBuffer）的传输。</li><li><strong>缺点</strong>：架构与开发复杂性较高；由于维护着持久长连接，对服务器端的系统架构、负载均衡策略和心跳监测设计提出了更严格的工程要求。</li></ul><hr><h2 id="_5-总结-技术选型对比" tabindex="-1">5. 总结：技术选型对比 <a class="header-anchor" href="#_5-总结-技术选型对比" aria-label="Permalink to “5. 总结：技术选型对比”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">短轮询 (Polling)</th><th style="text-align:left;">服务器推送事件 (SSE)</th><th style="text-align:left;">WebSocket</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>通信方向</strong></td><td style="text-align:left;">客户端主动轮询拉取 (单向)</td><td style="text-align:left;">服务端持续主动推送 (单向)</td><td style="text-align:left;">客户端与服务端享有平等收发权 (双向全双工)</td></tr><tr><td style="text-align:left;"><strong>底层协议</strong></td><td style="text-align:left;">标准 HTTP</td><td style="text-align:left;">标准 HTTP</td><td style="text-align:left;">独立的 WebSocket 协议 (基于 TCP)</td></tr><tr><td style="text-align:left;"><strong>数据开销</strong></td><td style="text-align:left;">极高 (包含完整的 HTTP 头部)</td><td style="text-align:left;">较低</td><td style="text-align:left;">极低 (极简的数据帧头部)</td></tr><tr><td style="text-align:left;"><strong>典型应用场景</strong></td><td style="text-align:left;">定时检查后台异步任务的完成状态</td><td style="text-align:left;">大模型对话单向流输出、新闻或系统通知推送</td><td style="text-align:left;">实时音视频信令、多人在线对战、协同白板与编辑</td></tr></tbody></table><p>在实际工程中，开发者应依据具体业务场景对实时性与双向交互频率的要求，在系统的维护复杂度和通信效率之间取得平衡，选择最契合的技术栈。</p>',6))])}const m=a(g,[["render",c]]);export{b as __pageData,m as default};
